import React, { useState, useEffect } from 'react';
import { View, Text, StatusBar, SafeAreaView, TouchableOpacity, ScrollView, ActivityIndicator, Alert, TextInput, Platform, ImageBackground } from 'react-native';
import styled from 'styled-components/native';
import Icon from '@expo/vector-icons/MaterialIcons';
import { colors, spacing, borderRadius } from '../../theme/tokens';
import api from '../../services/api';
import { useNavigation } from '@react-navigation/native';

// Fallback para MapView no Web
let MapView = View;
let Marker = View;
let PROVIDER_GOOGLE = null;

try {
  const Maps = require('react-native-maps');
  MapView = Maps.default || Maps;
  Marker = Maps.Marker;
  PROVIDER_GOOGLE = Maps.PROVIDER_GOOGLE;
} catch (e) {
  console.warn("Maps not available, using fallback");
}

const Container = styled.View`
  flex: 1;
  background-color: ${colors.background};
`;

const TopBar = styled.View`
  position: absolute;
  top: ${Platform.OS === 'ios' ? 50 : 30}px;
  left: ${spacing.md}px;
  right: ${spacing.md}px;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  z-index: 100; /* Garantir que fique acima de tudo */
`;

const IconButton = styled.TouchableOpacity`
  width: 45px;
  height: 45px;
  border-radius: ${borderRadius.full}px;
  background-color: ${colors.white};
  justify-content: center;
  align-items: center;
  elevation: 8;
  shadow-color: #000;
  shadow-offset: 0px 4px;
  shadow-opacity: 0.2;
  shadow-radius: 5px;
`;

const SearchCard = styled.View`
  position: absolute;
  top: ${Platform.OS === 'ios' ? 110 : 90}px;
  left: ${spacing.md}px;
  right: ${spacing.md}px;
  background-color: ${colors.white};
  border-radius: ${borderRadius.lg}px;
  padding: ${spacing.md}px;
  elevation: 10;
  shadow-color: #000;
  shadow-offset: 0px 5px;
  shadow-opacity: 0.1;
  shadow-radius: 8px;
  z-index: 90;
`;

const SearchRow = styled.View`
  flex-direction: row;
  align-items: center;
`;

const DotContainer = styled.View`
  align-items: center;
  margin-right: ${spacing.sm}px;
`;

const Dot = styled.View`
  width: 8px;
  height: 8px;
  border-radius: 4px;
  background-color: ${props => props.color || colors.primary};
`;

const Line = styled.View`
  width: 1px;
  height: 20px;
  background-color: #ddd;
  margin-vertical: 2px;
`;

const SearchInputRow = styled.View`
  flex: 1;
`;

const AddressText = styled.Text`
  font-size: 15px;
  color: ${props => props.placeholder ? colors.textSecondary : colors.text};
  font-weight: ${props => props.placeholder ? '400' : '500'};
`;

const Divider = styled.View`
  height: 1px;
  background-color: #f0f0f0;
  margin-vertical: ${spacing.sm}px;
`;

const AlterButton = styled.TouchableOpacity`
  background-color: #f5f5f5;
  padding-horizontal: ${spacing.md}px;
  padding-vertical: ${spacing.xs}px;
  border-radius: 20px;
`;

const AlterButtonText = styled.Text`
  font-size: 12px;
  font-weight: bold;
  color: ${colors.secondary};
`;

const BottomSheet = styled.View`
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: ${colors.white};
  border-top-left-radius: 25px;
  border-top-right-radius: 25px;
  padding-top: ${spacing.sm}px;
  padding-bottom: ${Platform.OS === 'ios' ? 40 : 20}px;
  elevation: 30;
  shadow-color: #000;
  shadow-offset: 0px -10px;
  shadow-opacity: 0.1;
  shadow-radius: 15px;
  z-index: 50;
`;

const Handle = styled.View`
  width: 40px;
  height: 5px;
  background-color: #e0e0e0;
  border-radius: 3px;
  align-self: center;
  margin-vertical: ${spacing.sm}px;
`;

const ContentPadding = styled.View`
  padding-horizontal: ${spacing.lg}px;
`;

const Greeting = styled.Text`
  font-size: 20px;
  font-weight: bold;
  color: ${colors.text};
  margin-bottom: 4px;
`;

const MainSearchButton = styled.TouchableOpacity`
  background-color: ${colors.background};
  border-radius: ${borderRadius.lg}px;
  height: 55px;
  flex-direction: row;
  align-items: center;
  padding-horizontal: ${spacing.md}px;
  margin-top: ${spacing.md}px;
  border-width: 1px;
  border-color: ${colors.border};
`;

const CategoryItem = styled.TouchableOpacity`
  flex-direction: row;
  align-items: center;
  padding-vertical: ${spacing.md}px;
  border-bottom-width: 1px;
  border-bottom-color: #f5f5f5;
  background-color: ${props => props.selected ? '#fcfdfc' : 'transparent'};
`;

const CategoryInfo = styled.View`
  flex: 1;
  margin-horizontal: ${spacing.sm}px;
`;

const CategoryName = styled.Text`
  font-size: 16px;
  font-weight: bold;
`;

const CategoryPrice = styled.Text`
  font-size: 16px;
  font-weight: bold;
`;

const ConfirmButton = styled.TouchableOpacity`
  background-color: #FFC107;
  height: 55px;
  border-radius: 30px;
  justify-content: center;
  align-items: center;
  margin-top: ${spacing.sm}px;
`;

const HomeScreen = () => {
  const navigation = useNavigation();
  const [isSelecting, setIsSelecting] = useState(false);
  const [isSelectingPayment, setIsSelectingPayment] = useState(false);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedCat, setSelectedCat] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState({ id: 'money', label: 'Dinheiro', icon: 'payments' });

  const [pickup, setPickup] = useState('Alameda Itu, 395');
  const [destination, setDestination] = useState('');

  const paymentOptions = [
    { id: 'money', label: 'Dinheiro', icon: 'payments' },
    { id: 'credit', label: 'Cartão de Crédito', icon: 'credit-card' },
    { id: 'wallet', label: 'Carteira UbeZap', icon: 'account-balance-wallet' },
  ];

  const toggleSelection = async () => {
    if (!isSelecting) {
      setLoading(true);
      setIsSelecting(true);
      setDestination('Básico Materiais Para Const...');
      try {
        const response = await api.passenger.getCategories(1);
        if (response.data && Array.isArray(response.data)) {
          setCategories(response.data);
          if (response.data.length > 0) setSelectedCat(response.data[0].id);
        }
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    } else {
      setIsSelecting(false);
      setIsSelectingPayment(false);
      setDestination('');
    }
  };

  const handleConfirm = () => {
    const cat = categories.find(c => c.id === selectedCat);
    if (!cat) return;
    Alert.alert('Sucesso', `Sua viagem de ${cat.nome} foi solicitada!\nPagamento: ${paymentMethod.label}`);
  };

  const renderMap = () => {
    if (Platform.OS === 'web') {
      return (
        <View style={{ flex: 1, backgroundColor: '#eef2f3', justifyContent: 'center', alignItems: 'center' }}>
          <Icon name="map" size={120} color="#cbd5e0" />
          <Text style={{ color: '#718096', marginTop: 15, fontSize: 18, fontWeight: '500' }}>Mapa Interativo (Web Fallback)</Text>
          <Text style={{ color: '#a0aec0', marginTop: 5 }}>No celular, o mapa do Google aparecerá aqui.</Text>
        </View>
      );
    }

    return (
      <MapView 
        style={{ flex: 1 }}
        provider={PROVIDER_GOOGLE}
        initialRegion={{
          latitude: -23.5505,
          longitude: -46.6333,
          latitudeDelta: 0.05,
          longitudeDelta: 0.05,
        }}
      >
        <Marker coordinate={{ latitude: -23.5505, longitude: -46.6333 }} title="Sua Localização" />
      </MapView>
    );
  };

  return (
    <Container>
      <StatusBar barStyle="dark-content" backgroundColor="transparent" translucent />

      <TopBar pointerEvents="box-none">
        <IconButton onPress={() => {
          if (isSelectingPayment) setIsSelectingPayment(false);
          else if (isSelecting) toggleSelection();
          else Alert.alert('Menu', 'Abrindo perfil do passageiro...');
        }}>
          <Icon name={(isSelecting || isSelectingPayment) ? "arrow-back" : "menu"} size={28} color={colors.secondary} />
        </IconButton>

        {isSelecting && (
           <SearchCard>
             <SearchRow>
               <DotContainer>
                 <Dot color="#2ecc71" />
                 <Line />
                 <Dot color="#e67e22" />
               </DotContainer>
               <SearchInputRow>
                 <AddressText>{pickup}</AddressText>
                 <Divider />
                 <AddressText placeholder={!destination}>{destination || 'Para onde vamos?'}</AddressText>
               </SearchInputRow>
               <AlterButton onPress={() => toggleSelection()}>
                 <AlterButtonText>Alterar</AlterButtonText>
               </AlterButton>
             </SearchRow>
           </SearchCard>
        )}

        <IconButton onPress={() => Alert.alert('Chat', 'Abrindo chat com suporte...')}>
          <Icon name="chat" size={24} color={colors.secondary} />
        </IconButton>
      </TopBar>

      {renderMap()}

      <BottomSheet expanded={isSelecting}>
        <Handle />

        <ContentPadding>
          {!isSelecting ? (
            <>
              <Greeting>Olá, Passageiro!</Greeting>
              <Text style={{ color: colors.textSecondary }}>Onde você quer ir?</Text>

              <MainSearchButton activeOpacity={0.8} onPress={toggleSelection}>
                <Icon name="search" size={24} color={colors.primary} />
                <Text style={{ flex: 1, marginLeft: 10, color: '#aaa', fontSize: 16 }}>Informe seu destino...</Text>
              </MainSearchButton>
            </>
          ) : isSelectingPayment ? (
            <>
              <Text style={{ fontSize: 18, fontWeight: 'bold', marginBottom: 20 }}>Forma de pagamento</Text>
              <ScrollView style={{ maxHeight: 300 }}>
                {paymentOptions.map((opt) => (
                  <TouchableOpacity 
                    key={opt.id} 
                    onPress={() => { setPaymentMethod(opt); setIsSelectingPayment(false); }}
                    style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 15, borderBottomWidth: 1, borderBottomColor: '#eee' }}
                  >
                    <Icon name={opt.icon} size={28} color={paymentMethod.id === opt.id ? "#f39c12" : "#aaa"} />
                    <Text style={{ flex: 1, marginLeft: 15, fontSize: 16 }}>{opt.label}</Text>
                    {paymentMethod.id === opt.id && <Icon name="check-circle" size={24} color={colors.primary} />}
                  </TouchableOpacity>
                ))}
              </ScrollView>
            </>
          ) : (
            <>
              <Text style={{ fontSize: 16, fontWeight: 'bold', marginBottom: 10 }}>Economize até R$8,00 nesta corrida</Text>

              {loading ? (
                <ActivityIndicator size="large" color={colors.primary} style={{ marginVertical: 30 }} />
              ) : (
                <ScrollView style={{ maxHeight: 250 }} showsVerticalScrollIndicator={false}>
                  {categories.map((cat) => (
                    <CategoryItem 
                      key={cat.id} 
                      selected={selectedCat === cat.id}
                      onPress={() => setSelectedCat(cat.id)}
                    >
                      <View style={{ width: 50, height: 40, justifyContent: 'center', alignItems: 'center' }}>
                         <Icon name="directions-car" size={35} color={selectedCat === cat.id ? colors.primary : '#aaa'} />
                      </View>
                      <CategoryInfo>
                        <CategoryName>{cat.nome}</CategoryName>
                        <Text style={{ fontSize: 12, color: '#999' }}>Chada em 4 min</Text>
                      </CategoryInfo>
                      <CategoryPrice>R$ {cat.tx_base || '14,90'}</CategoryPrice>
                      <View style={{ width: 20, height: 20, borderRadius: 10, borderWidth: 2, borderColor: selectedCat === cat.id ? colors.primary : '#ddd', marginLeft: 10, justifyContent: 'center', alignItems: 'center' }}>
                         {selectedCat === cat.id && <View style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: colors.primary }} />}
                      </View>
                    </CategoryItem>
                  ))}
                </ScrollView>
              )}

              <TouchableOpacity onPress={() => setIsSelectingPayment(true)} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 15, marginTop: 5 }}>
                <Icon name={paymentMethod.icon} size={24} color="#f39c12" />
                <Text style={{ flex: 1, marginLeft: 10, fontWeight: '500' }}>{paymentMethod.label} + Desconto</Text>
                <Icon name="chevron-right" size={20} color="#ccc" />
              </TouchableOpacity>

              <ConfirmButton onPress={handleConfirm}>
                <Text style={{ color: colors.secondary, fontSize: 18, fontWeight: 'bold' }}>
                  CONFIRMAR {categories.find(c => c.id === selectedCat)?.nome.toUpperCase() || 'VIAGEM'}
                </Text>
              </ConfirmButton>
            </>
          )}
        </ContentPadding>
      </BottomSheet>
    </Container>
  );
};

export default HomeScreen;
